cd build && python -c "
import numpy as np, itertools
from scipy.spatial.distance import cdist
L=open('lig_cis.xyz').read().split('\n'); n=int(L[0])
at=[];x=[]
for l in L[2:2+n]:
    p=l.split(); at.append(p[0]); x.append([float(v) for v in p[1:4]])
x=np.array(x); D=cdist(x,x)
cov={'C':0.77,'N':0.71,'P':1.07,'H':0.37}
for i,j in itertools.combinations(range(n),2):
    if D[i,j]<(cov[at[i]]+cov[at[j]])*1.3:
        if (at[i]=='H')+(at[j]=='H')==2 or D[i,j]>1.96: print(i,at[i],j,at[j],round(D[i,j],2))
